    "category": "14. Ejercicios Individuales",
    "subcategory": "Autopase y Remate de Precisión",
    "objetivoPrincipal": "Maximizar la autonomía y el perfeccionamiento técnico individual mediante autopase, control en carrera, golpeo de precisión en soledad, sin depender de compañeros.",
    "objetivoTecnico": "Toque sutil de balón, control orientado en espacios mínimos, sincronización del gesto y golpeos de precisión milimétrica.",
